                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await createTestRow(supabaseAdmin, userId, saveId, curETId, curET?.full_name ?? "", eType, isCumul ? 9999 : saveRow.start_page, isCumul ? 9999 : saveRow.end_page, { date: delayDate });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                